<script>
  import data from './data.json'; // Replace with your data source

  $: tableHeaders = Object.keys(data[0] || {}); // Use a rune to derive headers

  let sortedData = [...data]; // Create a copy to sort

  $: if (sortedData.length > 0) {
    console.log("Data updated");
  }

  function sortData(header) {
    sortedData.sort((a, b) => {
      if (a[header] < b[header]) return -1;
      if (a[header] > b[header]) return 1;
      return 0;
    });
  }
</script>

