      {#each tableHeaders as header}
        <th on:click={() => sortData(header)}>{header}</th>
      {/each}
    </tr>
  </thead>
  <tbody>
    {#each sortedData as row}
      <tr>
        {#each tableHeaders as header}
          <td>{row[header]}</td>
        {/each}
      </tr>
    {/each}
  </tbody>
</table>
